    "codigo": "// notificationService.js
const MAX_RETRIES = 3;

async function withRetry(label, sendFn) {
  let lastError;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    console.log(`[${label}] Tentativa ${attempt} — enviando`);
    try {
      await sendFn();
      console.log(`[${label}] Envio concluído com sucesso`);
      return;
    } catch (err) {
      lastError = err;
      console.error(`[${label}] Erro na tentativa ${attempt}: ${err.message}`);
    }
  }

  throw lastError;
}

async function sendEmail(to, subject, body) {
  await withRetry('Email', () => emailApi.send({ to, subject, body }));
}

async function sendSms(phoneNumber, text) {
  await withRetry('SMS', () => smsApi.send({ phoneNumber, text }));
}

async function sendPushNotification(deviceToken, title, message) {
  await withRetry('Push', () => pushApi.send({ deviceToken, title, message }));
}

module.exports = { sendEmail, sendSms, sendPushNotification };
",
